<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Shubham Thube | Data Analytics & Developer Portfolio</title>
    <style>
        :root {
            --bg-color: #0f172a;
            --card-bg: #1e293b;
            --accent-color: #38bdf8;
            --accent-hover: #0284c7;
            --text-color: #f8fafc;
            --text-muted: #94a3b8;
            --border-color: #334155;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            line-height: 1.6;
            padding-bottom: 50px;
        }

        header {
            max-width: 900px;
            margin: 60px auto 40px auto;
            padding: 0 20px;
            text-align: center;
        }

        h1 {
            font-size: 2.8rem;
            color: var(--text-color);
            margin-bottom: 10px;
        }

        h1 span {
            color: var(--accent-color);
        }

        p.subtitle {
            font-size: 1.2rem;
            color: var(--text-muted);
            margin-bottom: 25px;
        }

        .contact-links {
            display: flex;
            justify-content: center;
            gap: 15px;
            flex-wrap: wrap;
        }

        .btn {
            padding: 10px 20px;
            border-radius: 6px;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.95rem;
            transition: all 0.3s ease;
        }

        .btn-primary {
            background-color: var(--accent-color);
            color: #0f172a;
        }

        .btn-primary:hover {
            background-color: var(--accent-hover);
        }

        .btn-outline {
            border: 1px solid var(--border-color);
            color: var(--text-color);
            background-color: var(--card-bg);
        }

        .btn-outline:hover {
            border-color: var(--accent-color);
            color: var(--accent-color);
        }

        main {
            max-width: 900px;
            margin: 0 auto;
            padding: 0 20px;
        }

        section {
            background: var(--card-bg);
            border: 1px solid var(--border-color);
            border-radius: 10px;
            padding: 30px;
            margin-bottom: 30px;
        }

        h2 {
            font-size: 1.5rem;
            color: var(--accent-color);
            margin-bottom: 20px;
            border-bottom: 2px solid var(--border-color);
            padding-bottom: 8px;
        }

        .skills-grid {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }

        .tag {
            background-color: #0f172a;
            border: 1px solid var(--border-color);
            color: var(--text-color);
            padding: 8px 16px;
            border-radius: 20px;
            font-size: 0.9rem;
        }

        .project-card, .edu-item {
            margin-bottom: 20px;
        }

        .project-card:last-child, .edu-item:last-child {
            margin-bottom: 0;
        }

        .item-header {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
            flex-wrap: wrap;
            margin-bottom: 5px;
        }

        .item-title {
            font-size: 1.15rem;
            font-weight: bold;
            color: var(--text-color);
        }

        .item-subtitle {
            color: var(--accent-color);
            font-size: 0.95rem;
        }

        .item-date {
            color: var(--text-muted);
            font-size: 0.85rem;
        }

        ul.details {
            margin-left: 20px;
            color: var(--text-muted);
            margin-top: 10px;
        }

        ul.details li {
            margin-bottom: 6px;
        }

        footer {
            text-align: center;
            color: var(--text-muted);
            font-size: 0.85rem;
            margin-top: 40px;
        }
    </style>
</head>
<body>

